    ],
    "classroom_activity_design": {
      "warm_up": {
        "title": "Human Recursion",
        "duration": "10 minutes",
        "description": "Ask a student to say a simple sentence, then have the next student repeat it with one additional step. For example: 'I am calling myself' becomes a chain where each student adds one layer. Discuss how the activity needs a stopping rule to avoid going on forever."
      },
      "introduction": {
        "title": "What Is Recursion?",
        "duration": "10 minutes",
