      "direct_instruction": {
        "title": "Base Case and Recursive Case",
        "duration": "15 minutes",
        "description": "Present a simple recursive example, such as counting down from 5 to 0. Show that the base case is when the number reaches 0, and the recursive case is when the function calls itself with a smaller number. Emphasize that the function must get closer to the base case with each call."
      },
      "guided_practice": {
        "title": "Trace a Recursive Function",
        "duration": "15 minutes",
