      "objective": "Students will be able to reflect critically on challenges in implementing IHL in modern conflicts."
    }
  ],
  "key_points": [
    {
      "key_point": "Definition and purpose of IHL",
      "explanation": "IHL, also known as the law of armed conflict or the law of war, is a set of rules that seeks to limit the effects of armed conflict. It protects persons who are not or are no longer participating in hostilities and restricts the means and methods of warfare."
    },
    {
      "key_point": "Distinction",
      "explanation": "Parties to a conflict must distinguish between civilians and combatants, as well as between civilian objects and military objectives. Attacks may only be directed against military objectives."
    },
    {
      "key_point": "Proportionality",
      "explanation": "An attack is prohibited if it may be expected to cause incidental civilian harm that would be excessive in relation to the concrete and direct military advantage anticipated."
    },
    {
      "key_point": "Military necessity",
      "explanation": "Only acts of war that are necessary to achieve a legitimate military purpose are permitted, and measures that cause unnecessary suffering are prohibited."
    },
    {
      "key_point": "Humanity",
      "explanation": "Even in armed conflict, there are ethical and legal limits. The suffering of individuals, especially protected persons, must be reduced, and acts causing unnecessary injury or death are unlawful."
    },
    {
      "key_point": "Protected persons and objects",
      "explanation": "IHL protects civilians, wounded and sick persons, prisoners of war, medical personnel, and certain objects such as hospitals, schools, and humanitarian aid supplies."
    },
    {
      "key_point": "Means and methods of warfare",
      "explanation": "IHL prohibits certain weapons and methods, such as poison, biological weapons, chemical weapons, indiscriminate attacks, and perfidy."
    }
  ],
